'use strict';
// This standalone design prototype has no connection to game saves or economy.
const $ = (s, root=document) => root.querySelector(s);
const icons={settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h4l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3Z"/><circle cx="11" cy="12" r="3"/>',workshop:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',dex:'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-2-1-6-2-10 1Z"/>',craft:'<path d="m14 5 5-2-1 5-4 3-3-1-7 10-3-3 9-8-1-4 3-3Z"/>',research:'<path d="M8 17c0-4-4-4-4-9a8 8 0 0 1 16 0c0 5-4 5-4 9ZM8 20h8m-6 3h4"/>',garage:'<path d="m3 10 2-7h14l2 7v9H3Zm0 0h18M5 19v3m14-3v3M6 14h2m8 0h2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="m9 5 7 7-7 7"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/>',book:'<path d="M4 3h13l3 3v15H4Zm4 5h8M8 12h8m-8 4h5"/>',check:'<path d="m5 12 4 4L19 6"/>',box:'<path d="m12 2 10 5v10l-10 5-10-5V7Zm-10 5 10 5 10-5M12 12v10"/>',sound:'<path d="m3 9 5 0 5-5v16l-5-5H3Zm13-2c4 3 4 7 0 10m3-13c7 5 7 11 0 16"/>'};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.box}</svg>`;
const routes={workshop:'공방',dex:'도감',craft:'제작',research:'연구',garage:'차고'};
const state={part:'roof',material:'cr',crafted:false,garage:'owned',car:'d',pendingCar:'d',displayed:false,audio:false,mute:false,music:30,sfx:60,returnRoute:'',researchPanel:'',quizAnswer:'',quizResult:'',importPreview:false,resetArmed:false};
const parts={roof:{name:'루프',group:'바디 · 외판',art:'roof.png',purpose:'매끈한 곡면으로 차체의 지붕을 완성해요.'},dooro:{name:'도어 외판',group:'바디 · 외판',art:'dooro.png',purpose:'깊은 곡면과 깔끔한 표면을 함께 만들어요.'},bolt:{name:'볼트',group:'체결 · 선재',art:'bolt.png',purpose:'부품을 단단하게 이어 주는 작은 연결점이에요.'}};
let route='craft', toastTimer, resetTimer, settingsCaller, actionCaller;
const actionDialog=$('#action-dialog');const settings=$('#settings-dialog');
$('#settings-open').innerHTML=icon('settings');
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const heading=(eng,title,sub,aside='')=>`<div class="page-heading"><div><div class="eyebrow">${eng}</div><h1>${title}</h1><p>${sub}</p></div>${aside}</div>`;
const section=(n,title)=>`<h2><span class="section-number">${n}</span>${title}</h2>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function craft(){const p=parts[state.part];return heading('THE CRAFTING TABLE','나의 제작대','한 장의 소재가, 하나의 부품으로.',`<div class="counter"><b>${state.crafted?13:12}</b> / 35<small style="display:block">부품 예시</small></div>`)+`<div class="two-col"><section aria-label="부품 선택"><div class="scene"><div class="scene-label"><span>${p.group}</span><span class="stage-chip">선택한 부품</span></div><img src="art/${p.art}" width="310" height="220" alt="${p.name} 금속 부품 예시"><div class="scene-foot"><h2>${p.name}</h2><small>${p.purpose}</small></div></div><div class="section-heading">${section('01','부품 선택')}<small>3개 시연 / 전체 35개</small></div><div class="part-list">${Object.entries(parts).map(([id,p])=>btn(`<img src="art/${p.art}" alt="" width="72" height="64"><strong>${p.name}</strong><small>${id==='roof'?'추천 부품':'선택 가능'}</small>`,`part:${id}`,'part-option',`aria-pressed="${state.part===id}"`)).join('')}</div><div class="muted-box">선택한 부품과 소재를 먼저 확인하세요. 확정하기 전에는 재고를 사용하지 않아요.</div></section><section class="surface" aria-label="소재 선택"><div class="section-heading">${section('02','소재 선택')}<small>예시 재고</small></div>${state.part==='bolt'?`<p class="demo-label">볼트에 맞는 선재를 골라주세요.</p>`:''}<button class="material-option" data-action="material:cr" aria-pressed="${state.material==='cr'}"><span class="material-badge">${state.part==='bolt'?'WR':'CR'}</span><span><strong>${state.part==='bolt'?'WR SWRM':'CR DDQ'}</strong><small>${state.part==='bolt'?'일반 선재 · 체결용':'심가공용 · 외판 소재'}</small></span><span class="stock">보유 2장</span><span class="check">${state.material==='cr'?'✓':''}</span></button><button class="material-option" data-action="material:empty" aria-pressed="${state.material==='empty'}"><span class="material-badge">${state.part==='bolt'?'WR':'CR'}</span><span><strong>${state.part==='bolt'?'WR CHQ':'CR EDDQ'}</strong><small>${state.part==='bolt'?'냉간 압조용':'심가공 여유가 큰 소재'}</small></span><span class="stock">보유 0장</span><span class="check">${state.material==='empty'?'✓':''}</span></button><div class="divider"></div><div class="section-heading">${section('03','제작 전 확인')}</div><div class="cost-row"><span>만들 부품</span><strong>${p.name} 1개</strong></div><div class="cost-row"><span>사용할 재고</span><strong>${state.material==='empty'?'선택 소재 1장':'선택 소재 1장'}</strong></div><div class="cost-row"><span>제작 후 남는 재고</span><strong>${state.material==='empty'?'재고가 부족해요':'1장'}</strong></div>${state.material==='empty'?'<p class="error" role="alert">선택한 소재가 없어요. 다른 소재를 선택하거나 QP 개발 경로를 확인하세요.</p>':''}${btn(state.crafted?'다시 제작 검토':'제작 검토','craft-review','primary wide',state.material==='empty'?'disabled':'')}<button class="text-button wide" data-action="qp-link">QP 연구로 이동 ${icon('arrow')}</button><p class="small">QP 대체 가능 여부와 조건은 연구에서 확인해요.</p></section></div>`;}
function research(){return heading('RESEARCH & DISCOVERY','소재 연구실','알아갈수록, 만들 수 있는 것이 늘어나요.')+(state.returnRoute?btn(`← ${state.returnRoute==='craft'?'제작대로':'도감으로'} 돌아가기`,'research-return','text-button'):'')+`<div class="two-col"><section><div class="surface research-feature"><div><div class="eyebrow">ADVANCED MATERIAL</div><h2>가능성을 여는<br>QP 개발</h2><p>필요한 강도와 성형성.<br>다음 제작에 맞는 소재를 살펴봐요.</p>${btn('QP 개발 살펴보기','qp','primary')}</div><img src="art/qp_1470.jpg" width="170" height="255" alt="QP 큐피의 기존 금속 피규어 임시 원화"></div><div class="research-list"><button class="research-entry" data-action="quiz"><span class="entry-icon">${icon('research')}</span><strong>오늘의 퀴즈</strong><p>한 문제씩,<br>소재를 알아가는 시간.</p><span>퀴즈 풀기 →</span></button><button class="research-entry" data-action="order"><span class="entry-icon">${icon('book')}</span><strong>고객의 주문서</strong><p>요구 조건을 읽고<br>알맞은 소재를 찾아요.</p><span>주문서 보기 →</span></button></div></section><aside class="research-sidebar"><div class="eyebrow">YOUR RESEARCH NOTE</div><h2>공방의 작은 발견들</h2><p>연구가 어디에 쓰이는지, 실제 부품과 연결해서 살펴보세요.</p><div class="line-item"><span class="entry-icon">${icon('shield')}</span><div><h3>소재를 지켜 주는 보증</h3><p>보증의 의미와 적용 조건을 확인해요. 물성 수치가 오르는 효과는 아니에요.</p>${btn('보증 안내','guarantee','text-button')}</div></div><div class="line-item"><span class="entry-icon">${icon('dex')}</span><div><h3>작은 철강 이야기</h3><p>포오, 씨알, 도금이와 함께 읽는 공방의 이야기.</p>${btn('웹툰 읽기','webtoon','text-button')}</div></div><div class="muted-box">시안의 문제와 주문은 클릭 흐름을 위한 예시입니다. 실제 게임의 413문항·14주문·기존 웹툰은 후속 화면에서 연결합니다.</div></aside></div>`;}
function garage(){const carName=state.car==='h'?'중형 세단':'미니어처 로드스터';const empty=state.garage==='empty',complete=state.garage==='completion';return heading('THE DISPLAY GARAGE','나의 작은 차고',empty?'첫 완성차가 놓일 자리를 준비했어요.':'직접 만든 부품으로 완성한 나만의 컬렉션.',`<div class="counter"><b>${empty?0:1}</b> / 8<small style="display:block">보유 예시</small></div>`)+`<div class="segmented" aria-label="차고 시안 상태">${[['empty','빈 차고 보기'],['owned','보유 차량 보기'],['completion','완성 상태 보기']].map(([id,label])=>btn(label,`garage:${id}`,'',`aria-pressed="${state.garage===id}"`)).join('')}</div><div class="two-col"><section><div class="scene garage-scene"><div class="scene-label"><span>${empty?'첫 번째 전시 공간':complete?'ASSEMBLY COMPLETE':'COLLECTION 01'}</span><span class="stage-chip">예시 상태</span></div>${empty?`<div class="empty-stage">${icon('garage')}<h2>아직 완성한 차가 없어요</h2><p>부품을 하나씩 모아<br>첫 번째 자동차를 완성해 보세요.</p></div>`:`<img src="art/${state.car}.png" width="400" height="270" alt="${carName} 임시 원화">`}<div class="scene-foot"><small>${empty?'빈 차고에는 미보유 차량을 전시하지 않아요.':'기존 차량 원화 · 신규 원화 제작 전 임시 사용'}</small></div></div><div class="garage-meta"><div><h2>${empty?'나의 첫 완성을 향해':carName}</h2><p>${complete?'35개 부품의 작은 결실. 이제 전시할 수 있어요.':empty?'제작대에서 다음 부품을 선택해 보세요.':state.car==='h'?'낮고 길게 뻗은 세단 차체':'아이보리 · 블랙 루프 · 따뜻한 구리빛'}</p></div>${!empty?'<span class="pill">'+(state.displayed?'대표 전시':'보유 예시')+'</span>':''}</div>${empty?btn('제작대 열기','go-craft','primary wide'):btn(state.displayed?'대표 전시로 선택됨':'대표 전시로 선택','display-car','primary wide',state.displayed?'disabled':'')}</section><section class="surface"><div class="section-heading"><h2>${complete?'완성한 부품':'조립 기록'}</h2><small>예시</small></div><div class="stats"><div><small>부품 완성</small><strong>${complete?'35':'12'} <small style="display:inline">/ 35</small></strong></div><div><small>다음 부품</small><strong>${complete?'모두 완료':'루프'}</strong></div></div><div class="progress" aria-label="부품 완성 예시 ${complete?35:12}/35"><span style="width:${complete?100:34}%"></span></div><p class="small">${complete?'모든 부품을 모았어요. 미보유 차량을 선택하는 단계로 이어져요.':'바디, 구조, 구동 부품을 모아 한 대의 차를 완성해요.'}</p><div class="collection-row"><img src="art/roof.png" alt="루프 부품" width="100" height="80"><div><h3>루프</h3><p>${complete?'제작 완료 예시':'다음 제작 추천 · CR DDQ 1장'}</p>${btn('제작대에서 보기','go-craft','text-button')}</div></div><div class="section-heading"><h3>${complete?'완성차 선택':'내 컬렉션'}</h3></div>${complete?`<label class="field-label" for="car-choice">미보유 차량 선택 예시</label><select id="car-choice"><option value="d">로드스터</option><option value="h">중형 세단</option></select>${btn('완성차 선택 확인','assemble','primary wide')}`:empty?'<p>아직 소유한 차량이 없어요. 차량을 완성하면 이곳에 추가됩니다.</p>':`<div class="collection-row"><img src="art/${state.car}.png" alt="보유 예시 ${carName}" width="100" height="80"><div><h3>${carName}</h3><p>보유 예시 · 전시 선택 가능</p></div></div>`}</section></div>`;}
function reference(){const isHome=route==='workshop';return heading('APPROVED DESIGN REFERENCES',isHome?'공방 디자인 참조':'도감 디자인 참조','이 화면은 승인된 원본 시안을 보는 갤러리입니다.')+`<p class="demo-label">상호작용 상세 시안은 제작·연구·차고·설정에서 확인하세요.</p><div class="reference-grid">${(isHome?[['workshop','나의 공방'],['equipment-car','피규어와 완성차']]:[['gallery','컬렉션'],['equipment','장비 장착'],['cards','일반·특별 카드']]).map(([file,title])=>`<figure><a href="../game-reference/${file}.png"><img src="../game-reference/${file}.png" alt="승인된 ${title} 시안 원본" loading="lazy" width="853" height="1844">${title} 원본 보기</a><figcaption><p>참조 이미지이며 실제 게임 화면이나 소유 상태가 아닙니다.</p></figcaption></figure>`).join('')}</div>`;}
function render(){const focusAction=document.activeElement?.dataset?.action;let hash=location.hash.slice(1)||'craft';if(['learn','learning'].includes(hash)){hash='research';history.replaceState(null,'','#research');}if(!Object.hasOwn(routes,hash)){hash='craft';history.replaceState(null,'','#craft');}route=hash;$('#content').innerHTML=route==='craft'?craft():route==='research'?research():route==='garage'?garage():reference();$('#navigation').innerHTML=Object.entries(routes).map(([id,label])=>`<a href="#${id}" ${id===route?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('');document.title=`${routes[route]} · Steel Companion 디자인 시안`;if(focusAction){const target=Array.from(document.querySelectorAll('[data-action]')).find(x=>x.dataset.action===focusAction);target?.focus({preventScroll:true});}}
function closeAction(){actionDialog.close();if(actionCaller?.isConnected)actionCaller.focus();}
function showDialog(title,body,actions=''){actionCaller=document.activeElement;actionDialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn(icon('close'),'close-action','icon-button','aria-label="닫기" autofocus')}</div><div class="dialog-body"><p class="demo-label">디자인 시안 · 실제 진행 변경 없음</p>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}</div>`;actionDialog.showModal();actionDialog.scrollTo({top:0,behavior:'instant'});}
function settingsView(){settings.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">MAKE YOURSELF AT HOME</div><h2 id="settings-title">공방 설정</h2></div>${btn(icon('close'),'close-settings','icon-button','aria-label="설정 닫기" autofocus')}</div><div class="dialog-body"><p class="demo-label">디자인 시안 · 실제 저장·소리 재생 없음</p><div class="section-heading"><h3>소리와 분위기</h3><span class="entry-icon">${icon('sound')}</span></div><div class="settings-line"><span><strong>공방의 소리</strong><small>${state.audio?'소리 사용을 선택했어요.':'직접 켜기 전까지 조용히 시작해요.'}</small></span>${btn(state.audio?'소리 끄기':'소리 켜기','audio-enable',state.audio?'':'primary')}</div><div class="settings-line"><span><strong>전체 음소거</strong><small>음악과 효과음을 함께 꺼요.</small></span><button class="switch" data-action="mute" role="switch" aria-label="전체 음소거" aria-checked="${state.mute}"></button></div><label class="range-label" for="music-volume">음악 음량 <output id="music-output">${state.music}%</output></label><input id="music-volume" type="range" min="0" max="100" step="1" value="${state.music}"><label class="range-label" for="sfx-volume">효과음 음량 <output id="sfx-output">${state.sfx}%</output></label><input id="sfx-volume" type="range" min="0" max="100" step="1" value="${state.sfx}"><div class="divider"></div><div class="section-heading"><h3>게임 진행 보관</h3></div><p>게임용 저장은 교육용과 분리됩니다. 가져오기는 직접 선택했을 때만 진행해요.</p><div class="settings-actions" style="margin-top:16px">${btn('게임 백업 만들기','backup-export')}${btn('교육용 백업 가져오기','backup-import')}${btn('회복 코드 보기','recovery')}${btn('설치 안내','install')}</div><div class="divider"></div><div class="settings-line"><span><strong>처음부터 다시 시작</strong><small>확인 후 5초 안에 한 번 더 선택해요.</small></span>${btn('게임 진행 초기화','reset','danger')}</div></div>`;}
$('#settings-open').addEventListener('click',()=>{settingsCaller=document.activeElement;settingsView();settings.showModal();settings.scrollTo({top:0,behavior:'instant'});});
settings.addEventListener('close',()=>{if(settingsCaller?.isConnected)settingsCaller.focus();});actionDialog.addEventListener('cancel',()=>{queueMicrotask(()=>actionCaller?.isConnected&&actionCaller.focus());});
settings.addEventListener('input',e=>{if(e.target.id==='music-volume'){state.music=+e.target.value;$('#music-output').value=state.music+'%';}if(e.target.id==='sfx-volume'){state.sfx=+e.target.value;$('#sfx-output').value=state.sfx+'%';}});
function handle(action){
 if(action.startsWith('part:')){state.part=action.split(':')[1];state.material='cr';render();return;}
 if(action.startsWith('material:')){state.material=action.split(':')[1];render();return;}
 if(action.startsWith('garage:')){state.garage=action.split(':')[1];state.displayed=false;render();return;}
 if(action.startsWith('answer:')){state.quizAnswer=action.split(':')[1];document.querySelectorAll('.answer').forEach(x=>x.setAttribute('aria-pressed',x.dataset.action===action));$('#quiz-result').textContent=state.quizAnswer==='ductile'?'정답이에요. 깊은 형상에는 성형성이 필요해요.':'다시 생각해 보세요. 복잡한 형상은 잘 늘어나는 소재가 필요해요.';return;}
 switch(action){
 case 'go-craft':location.hash='craft';break;
 case 'qp-link':state.returnRoute=route;location.hash='research';break;
 case 'research-return':{const target=state.returnRoute;state.returnRoute='';location.hash=target||'craft';break;}
 case 'craft-review':showDialog('이 부품을 만들까요?',`<h3>${parts[state.part].name} 1개</h3><div class="cost-row"><span>사용 소재</span><strong>${state.part==='bolt'?'WR SWRM':'CR DDQ'} 1장</strong></div><div class="cost-row"><span>남는 예시 재고</span><strong>2장 → 1장</strong></div><p style="margin-top:16px">확정하면 제작 완료 상태를 시연해요. 실제 재고는 사용하지 않습니다.</p>`,btn('취소','close-action')+btn('제작 확정','craft-confirm','primary'));break;
 case 'craft-confirm':state.crafted=true;closeAction();render();toast('제작 완료 예시 · 실제 재고 변경 없음');break;
 case 'close-action':closeAction();break;
 case 'close-settings':settings.close();break;
 case 'qp':showDialog('QP 개발',`<h3>제작에 필요한 소재를 찾아요</h3><p>선행개발 소재 QP의 적용 조건을 살펴보는 단계예요. 일반 출하 보상이나 승급은 아닙니다.</p><label class="field-label" for="qp-slot">대체할 부품 슬롯</label><select id="qp-slot"><option>루프 · 소재 조건 확인</option><option>도어 외판 · 소재 조건 확인</option></select><div class="muted-box">예시 조건: 재료·강도·성형 조건을 모두 충족한 경우에만 대체를 확정합니다.</div>`,btn('닫기','close-action')+btn('조건 확인','qp-check','primary'));break;
 case 'qp-check':$('#action-dialog .muted-box').textContent='조건 확인 예시 완료. 실제 대체 가능 여부는 게임의 부품 규칙으로 계산합니다.';break;
 case 'quiz':showDialog('오늘의 퀴즈',`<div class="eyebrow">QUESTION 01 · 예시</div><h3>깊은 곡면의 외판을 만들 때,<br>먼저 살펴볼 성질은 무엇일까요?</h3><div class="radio-list">${btn('성형성','answer:ductile','answer','aria-pressed="false"')}${btn('색상만 비교','answer:color','answer','aria-pressed="false"')}</div><p id="quiz-result" role="status" style="margin-top:16px">답을 선택하면 해설을 확인할 수 있어요.</p>`);break;
 case 'order':showDialog('고객의 주문서',`<div class="eyebrow">WORKSHOP ORDER · 예시</div><h3>깊게 성형하는 자동차 외판</h3><p style="margin-top:12px">복잡한 곡면을 만들 수 있는 소재가 필요해요. 표면 품질과 성형성을 함께 확인하세요.</p><label class="field-label" for="order-material">검토할 소재</label><select id="order-material"><option>CR DDQ</option><option>CR EDDQ</option></select><p class="muted-box" id="order-result">시안에서는 조건 확인 흐름만 제공합니다.</p>`,btn('닫기','close-action')+btn('요구 조건 확인','order-check','primary'));break;
 case 'order-check':$('#order-result').textContent='선택한 소재의 성형 조건을 확인했어요. 실제 게임에서는 주문의 모든 요구 조건을 검사합니다.';break;
 case 'guarantee':showDialog('보증 안내',`<div class="entry-icon">${icon('shield')}</div><h3 style="margin-top:16px">방패 · 외관 보증</h3><p>외판용 소재의 표면 품질을 보증해요. 보증 장비는 조건을 충족하는 소재에 적용되며, 물성 수치가 올라가는 효과는 아니에요.</p><div class="muted-box">보유·호환 조건을 확인한 뒤 도감의 장비 화면에서 장착합니다.</div>`,btn('닫기','close-action'));break;
 case 'webtoon':showDialog('작은 철강 이야기',`<h3>기존 웹툰 목록</h3><p>원본의 3개 항목과 18개 이미지를 보존하는 읽기 화면으로 이어집니다.</p><div class="radio-list">${btn('연재 안내','toon:notice')}${btn('1화 · 이야기 열기','toon:1')}${btn('2화 · 이야기 열기','toon:2')}</div><p id="toon-result" role="status" style="margin-top:16px">읽을 항목을 선택해 보세요.</p>`);break;
 case 'display-car':state.displayed=true;render();toast('대표 전시 선택 예시가 반영됐어요.');break;
 case 'assemble':state.pendingCar=$('#car-choice').value;showDialog('완성차 선택 확인',`<h3>${$('#car-choice').selectedOptions[0].textContent}</h3><p style="margin-top:12px">미보유 차량을 선택하는 예시입니다. 취소하면 차고 선택 상태로 돌아가요.</p>`,btn('취소','close-action')+btn('선택 확정','assemble-confirm','primary'));break;
 case 'assemble-confirm':closeAction();state.car=state.pendingCar;state.displayed=false;state.garage='owned';render();toast('완성차 선택 흐름 확인 · 실제 차량 지급 없음');break;
 case 'audio-enable':state.audio=!state.audio;settingsView();$('[data-action="audio-enable"]',settings).focus();break;
 case 'mute':state.mute=!state.mute;const mute=$('[data-action="mute"]');mute.setAttribute('aria-checked',state.mute);break;
 case 'backup-export':showDialog('게임 백업 예시',`<p>아래는 시연용 토큰입니다. 실제 진행 데이터가 아니며 게임에 가져올 수 없습니다.</p><label class="field-label" for="backup-code">예시 백업</label><textarea id="backup-code" readonly>DEMO-GAME-BACKUP-NOT-REAL</textarea>`,btn('닫기','close-action'));break;
 case 'backup-import':state.importPreview=false;showDialog('교육용 백업 가져오기',`<p>자동으로 가져오지 않습니다. 실제 게임에서는 요약과 이전 게임 회복 코드를 확인한 뒤 교체를 확정합니다.</p><label class="field-label" for="import-code">시연용 코드를 입력하세요</label><textarea id="import-code" placeholder="DEMO-EDUCATION" spellcheck="false"></textarea><p class="small">테스트 토큰: DEMO-EDUCATION. 개인 백업 코드는 입력하지 마세요.</p><div id="import-result" role="status"></div>`,btn('취소','close-action')+btn('가져오기 미리보기','import-preview','primary'));break;
 case 'import-preview':{const value=$('#import-code').value.trim();if(value!=='DEMO-EDUCATION'){$('#import-result').textContent='시연용 코드가 아니에요. DEMO-EDUCATION을 입력해 주세요.';$('#import-result').className='error';return;}state.importPreview=true;$('#import-result').className='muted-box';$('#import-result').textContent='교육용 → 게임용 예시 요약: 카드 3종, 부품 2개. 오디오·대표 전시 설정은 제외. 회복 코드: DEMO-RECOVERY. 실제 데이터는 읽거나 변경하지 않습니다.';const b=$('[data-action="import-preview"]');b.textContent='교체 확정 시연';b.dataset.action='import-confirm';break;}
 case 'import-confirm':closeAction();toast('가져오기 확인 흐름 완료 · 실제 저장 변경 없음');break;
 case 'recovery':showDialog('이전 게임 회복 코드',`<p>교체 전 게임 진행을 되돌리기 위한 코드가 여기에 표시됩니다.</p><label class="field-label" for="recovery-code">회복 코드 예시</label><textarea id="recovery-code" readonly>DEMO-RECOVERY-NOT-REAL</textarea>`,btn('닫기','close-action'));break;
 case 'install':showDialog('게임용 앱 설치 안내',`<p>실제 배포에서는 브라우저의 설치 기능으로 게임판을 별도 설치합니다. 이 문서는 디자인 프로토타입으로 앱 설치나 권한 요청을 실행하지 않습니다.</p>`,btn('닫기','close-action'));break;
 case 'reset':state.resetArmed=false;showDialog('게임 진행을 초기화할까요?',`<p>교육용 데이터는 영향을 받지 않습니다. 실제 게임에서는 게임용 진행만 초기화됩니다.</p><div id="reset-status" class="muted-box" role="status">먼저 초기화 준비를 선택하세요.</div>`,btn('취소','close-action')+btn('초기화 준비','reset-arm','danger'));break;
 case 'reset-arm':{state.resetArmed=true;$('#reset-status').textContent='5초 안에 다시 선택하면 초기화 완료 상태를 시연합니다.';let b=$('[data-action="reset-arm"]');b.dataset.action='reset-confirm';b.textContent='초기화 확정';clearTimeout(resetTimer);resetTimer=setTimeout(()=>{state.resetArmed=false;let b=$('[data-action="reset-confirm"]');if(b){b.dataset.action='reset-arm';b.textContent='초기화 준비';$('#reset-status').textContent='확인 시간이 지났어요. 다시 준비해 주세요.';}},5000);break;}
 case 'reset-confirm':if(state.resetArmed){state.resetArmed=false;clearTimeout(resetTimer);closeAction();toast('초기화 흐름 시연 완료 · 실제 저장 변경 없음');}break;
 default:if(action.startsWith('toon:'))$('#toon-result').textContent=`${action==='toon:notice'?'연재 안내':action.split(':')[1]+'화'} 선택됨 · 이 상세 시안에서는 목록 진입과 복귀를 확인합니다.`;
 }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)handle(b.dataset.action);});
window.addEventListener('hashchange',()=>{if(actionDialog.open)actionDialog.close();if(settings.open)settings.close();render();window.scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true});});render();
